R, C = map(int, input().split())
grid = [input() for _ in range(R)]

new_grid = []
for r in range(R):
    line = ""
    for c in range(C):
        count = 0
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == "#":
                    count += 1
        if grid[r][c] == "#":
            alive = count == 2 or count == 3
        else:
            alive = count == 3
        line += "#" if alive else "."
    new_grid.append(line)
for line in new_grid:
    print(line)
